sob carga o serviço começa a dar timeout e o log enche de 'Connection is not available, request timed out after 30000ms' do Hikari. já subimos o maximumPoolSize de 10 pra 50 e melhorou um pouco mas voltou. a CPU do Oracle tá em 20%. segue o método:

@Transactional
public void registrarPassagem(PassagemDTO dto, List<MultipartFile> imagens) {
    Passagem p = passagemRepository.save(dto.toEntity());
    for (MultipartFile img : imagens) {
        byte[] bytes = img.getBytes();
        String chave = storageClient.upload(bytes, p.getId());
        imagemRepository.save(new Imagem(p, chave));
    }
    if (dto.getVelocidade() > dto.getLimite()) {
        autuacaoService.gerarAutoInfracao(p);
    }
}
